def compute(vars):
    gross_liability = vars["v2"]
    if gross_liability == 0:
        return None

    ratio = vars["v1"] / gross_liability
    value = ratio * 100

    return {
        "value": value,
        "trace": {
            "unrecognized_tax_benefit": vars["v1"],
            "gross_liability": gross_liability,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
